        return .{ .fd = .{ .writer = IOWriter.init(pipes[@as(usize, @intCast(proc_idx))][1], .{ .pollable = true, .is_socket = bun.Environment.isPosix }, evtloop) } };
}

pub fn readPipe(pipes: []Pipe, proc_idx: usize, io: *IO, evtloop: jsc.EventLoopHandle) IO.InKind {
        if ((proc_idx == 0)) {
            return io.stdin.ref();
        }
        return .{ .fd = IOReader.init(pipes[@as(usize, @intCast((proc_idx - 1)))][0], evtloop) };
}
